cd "C:/visual projects/role-play-vibing/.claude/worktrees/tk020" && echo "radon E/F:" $(python -m radon cc -s -n E .claude/ | grep -cE '^\s+[FMC] ') && python - <<'EOF'
import ast,pathlib
mf=(0,'');mfn=(0,'')
for p in pathlib.Path('.claude').rglob('*.py'):
    if 'worktrees' in p.parts: continue
    s=p.read_text(encoding='utf-8');n=s.count('\n')
    if n>mf[0]: mf=(n,str(p))
    for f in ast.walk(ast.parse(s)):
        if isinstance(f,(ast.FunctionDef,ast.AsyncFunctionDef)):
            l=f.end_lineno-f.lineno+1
            if l>mfn[0]: mfn=(l,f'{p}:{f.name}')
print('max file',mf);print('max func',mfn)
EOF
grep -c "import \*" .claude/hooks/delete_guard.py; grep -c "noqa: F401" .claude/dispatcher/dispatch.py; wc -l < .claude/dispatcher/dispatch.py; ls .claude/dispatcher/ | grep -E "cfg|config|paths"; python -m pyflakes .claude/dispatcher/*.py .claude/hooks/*.py 2>/dev/null | grep -v "/test_" | grep -c "imported but unused"

